SITE='https://bryantvending.co.uk'
css='''*{box-sizing:border-box}body{margin:0;color:#132d4e;background:#fff;font-family:Arial,sans-serif;font-size:17px;line-height:1.65}a{color:inherit}header{border-bottom:1px solid #e3e9ed;background:white}nav{max-width:1150px;margin:auto;display:flex;align-items:center;justify-content:space-between;padding:18px 24px;gap:20px}.logo{width:255px;max-width:60vw;height:auto;display:block}nav .links{display:flex;gap:27px;align-items:center}nav a{text-decoration:none;font-weight:bold;font-size:15px}.button{display:inline-block;background:#66b71d;color:#102b4b;border:0;border-radius:6px;padding:14px 23px;text-decoration:none;font-weight:700}.button:hover{background:#83d63b}.wrap{max-width:1150px;margin:auto;padding:0 24px}.hero{background:#102d50;color:white}.hero .wrap{min-height:470px;display:grid;grid-template-columns:1.15fr .85fr;gap:50px;align-items:center;padding-top:72px;padding-bottom:72px}.eyebrow{font-size:13px;letter-spacing:.16em;text-transform:uppercase;color:#a9e078;font-weight:bold}h1{font-size:clamp(2.7rem,5.7vw,4.8rem);line-height:1.06;letter-spacing:-.04em;margin:18px 0 22px}h2{font-size:clamp(2rem,4vw,3rem);line-height:1.14;letter-spacing:-.03em;margin:0 0 20px}h3{font-size:1.25rem;margin-bottom:5px}.hero p{font-size:1.15rem;color:#d5e0e9;max-width:570px}.machine{background:#1c426a;border:1px solid #507193;border-radius:20px;padding:28px;max-width:350px;margin:auto;box-shadow:0 25px 60px #061b3599}.screen{background:#eef6fa;border-radius:10px;padding:24px;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.product{height:70px;border-radius:6px;background:#8bcf55}.product:nth-child(even){background:#d4e7f0}.machine span{display:block;color:#dbe9f3;margin-top:15px;text-align:center;font-size:.9rem}.section{padding:88px 0}.soft{background:#f2f7f5}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.grid article{border-top:3px solid #71bf31;padding-top:12px}.muted{color:#4b6378}.cta{background:#dcf2ce;border-radius:16px;padding:45px;display:flex;justify-content:space-between;gap:30px;align-items:center}.cta h2{font-size:2rem}.page{max-width:800px;margin:auto;padding:75px 24px 100px}.page h1{font-size:3.3rem}.page h2{font-size:1.5rem;margin-top:40px}.notice{background:#eef7e9;padding:22px;border-left:4px solid #65b82b}footer{background:#0c2543;color:#d4e1ea;padding:45px 0}footer .wrap{display:flex;justify-content:space-between;gap:25px}footer a{margin-left:20px}.offer{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:34px}.offer div{background:white;border-radius:12px;padding:24px;border:1px solid #dbe7df}.offer strong{display:block;font-size:1.1rem;margin-bottom:6px}.contact-actions{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0 6px}.button.alt{background:#102d50;color:white}.small{font-size:.9rem}@media(max-width:720px){nav{align-items:flex-start;flex-direction:column}nav .links{gap:17px;flex-wrap:wrap}.hero .wrap,.grid{grid-template-columns:1fr}.hero .wrap{padding-top:54px;padding-bottom:54px}.machine{width:240px}.product{height:48px}.section{padding:60px 0}.cta,footer .wrap{display:block}.offer{grid-template-columns:1fr}.cta .button{margin-top:10px}.cta{padding:28px}footer a{margin:0 18px 0 0}.page h1{font-size:2.6rem}}'''
(p/'styles.css').write_text(css)
header='''<header><nav><a href="index.html" aria-label="Bryant Vending Services home"><img class="logo" src="logo.png" alt="Bryant Vending Services" width="255" height="85"></a><div class="links"><a href="index.html">Home</a><a href="index.html#service">How it works</a><a href="index.html#options">Options</a><a href="contact.html">Contact us</a></div></nav></header>'''
footer='''<footer><div class="wrap"><div><strong>Bryant Vending Services</strong><br>A trading name of Bryant Group Holdings Ltd · Company no. 13671131<br>Serving Bournemouth, Poole, Christchurch &amp; Dorset</div><div><a href="contact.html">Contact</a><a href="privacy.html">Privacy</a></div></div></footer>'''
def page(file,title,desc,body):
    url=SITE+'/'+('' if file=='index.html' else file)
    ld='' if file!='index.html' else '<script type="application/ld+json">{"@context":"https://schema.org","@type":"LocalBusiness","name":"Bryant Vending Services","url":"https://bryantvending.co.uk/","logo":"https://bryantvending.co.uk/logo.png","image":"https://bryantvending.co.uk/logo.png","email":"info@bryantvending.co.uk","telephone":"+447843969254","areaServed":["Bournemouth","Poole","Christchurch","Dorset"],"parentOrganization":{"@type":"Organization","name":"Bryant Group Holdings Ltd"}}</script>'
    return f'<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:site_name" content="Bryant Vending Services"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:image" content="{SITE}/logo.png"><meta name="twitter:card" content="summary"><meta name="theme-color" content="#102d50"><link rel="icon" type="image/png" href="favicon.png"><link rel="apple-touch-icon" href="apple-touch-icon.png"><link rel="stylesheet" href="styles.css">{ld}</head><body>{header}<main>{body}</main>{footer}</body></html>'

home='''<section class="hero"><div class="wrap"><div><div class="eyebrow">Vending for workplaces &amp; venues</div><h1>Refreshments, right where you need them.</h1><p>Snack and drink vending for workplaces, gyms and venues across Bournemouth, Poole and Dorset.</p><a class="button" href="contact.html">Discuss your location</a></div><div class="machine" role="img" aria-label="Illustration of a refreshments vending machine"><div class="screen"><i class="product"></i><i class="product"></i><i class="product"></i><i class="product"></i><i class="product"></i><i class="product"></i></div><span>Snacks &amp; drinks, made convenient</span></div></div></section><section class="section" id="service"><div class="wrap"><div class="eyebrow" style="color:#478d19">A simple service</div><h2>Good refreshment starts with the right fit.</h2><p class="muted">Every location is different. We’ll discuss your space and the people who use it to explore an appropriate vending setup.</p><div class="grid"><article><h3>Tell us about your space</h3><p class="muted">Share your location, the people you serve and what you’re looking for.</p></article><article><h3>Explore your options</h3><p class="muted">We’ll discuss machine and product options, as well as the practical details.</p></article><article><h3>Agree the next steps</h3><p class="muted">If the location is suitable, we’ll talk through the proposed arrangement and costs.</p></article></div></div></section><section class="section soft" id="options"><div class="wrap"><div class="eyebrow" style="color:#478d19">Flexible arrangements</div><h2>Options to suit your site.</h2><p class="muted">Depending on the location, we can discuss providing and managing a suitable machine at no charge to your business. Everything is agreed with you in advance.</p><div class="offer"><div><strong>Machine at no charge</strong><span class="muted">Subject to the location and an agreed arrangement.</span></div><div><strong>Commission share</strong><span class="muted">A share of sales from the machine on your premises.</span></div><div><strong>Space rental</strong><span class="muted">Or we can discuss renting the space from you.</span></div></div><p class="muted small">Product prices and any other terms are agreed before anything is installed.</p></div></section><section class="section"><div class="wrap"><div class="cta"><div><h2>Have a place in mind?</h2><p>Let’s talk about what could work for your location. Call <a href="tel:+447843969254">07843 969254</a> or send us a message.</p></div><a class="button" href="contact.html">Contact us</a></div></div></section>'''
contact='''<div class="page"><div class="eyebrow" style="color:#478d19">Get in touch</div><h1>Let’s talk vending.</h1><p>Interested in a vending machine for your workplace or venue? Tell us a little about your location and what you need.</p><div class="notice"><strong>Contact Bryant Vending Services</strong><div class="contact-actions"><a class="button" href="tel:+447843969254">Call 07843 969254</a><a class="button alt" href="https://wa.me/447843969254?text=Hi%2C%20I%27m%20interested%20in%20a%20vending%20machine%20for%20my%20location.">WhatsApp us</a><a class="button alt" href="mailto:info@bryantvending.co.uk?subject=Vending%20enquiry">Email us</a></div><p>Email: <a href="mailto:info@bryantvending.co.uk?subject=Vending%20enquiry">info@bryantvending.co.uk</a><br>Phone: <a href="tel:+447843969254">07843 969254</a><br>WhatsApp: <a href="https://wa.me/447843969254">Message us on WhatsApp</a></p></div><h2>Helpful details to share</h2><p>Your business or venue, its location, the number of people using the space and the types of refreshments you have in mind.</p></div>'''
privacy='''<div class="page"><div class="eyebrow" style="color:#478d19">Your information</div><h1>Privacy notice</h1><p class="muted">Last updated: 21 November 2026</p><h2>Who we are</h2><p>Bryant Vending Services is a trading name of Bryant Group Holdings Ltd (company no. 13671131), registered office 32 Heaton Road, Bournemouth, BH10 5HW. We are the controller of the personal information described here.</p><h2>What we collect and why</h2><p>This website has no forms, cookies, tracking or analytics. If you contact us by email, phone or WhatsApp, we use your name, contact details and what you tell us about your location to reply to your enquiry and, if you go ahead, to agree and manage a vending arrangement. Our lawful basis is our legitimate interest in responding to enquiries, or taking steps towards a contract at your request.</p><p>We may email businesses whose contact details are publicly listed to ask whether vending could be useful to them. Every such email lets you opt out, and we will not contact you again if you ask us not to.</p><h2>Who we share it with</h2><p>We do not sell your information. It is held with our email and phone providers, and shared with others only where needed to provide the service or where the law requires. The website itself is hosted by GitHub Pages, which may log visitors' IP addresses for security.</p><h2>How long we keep it</h2><p>Enquiries that do not go ahead are deleted within 12 months. Records for agreed arrangements are kept for as long as the arrangement runs and then for up to 6 years for legal and accounting purposes.</p><h2>Your rights</h2><p>You can ask for a copy of your information, ask us to correct or delete it, or object to how we use it, including asking us to stop contacting you. Email <a href="mailto:info@bryantvending.co.uk">info@bryantvending.co.uk</a>. If you are unhappy with how we handle your information you can complain to the Information Commissioner's Office at <a href="https://ico.org.uk">ico.org.uk</a>.</p></div>'''
notfound='''<div class="page"><div class="eyebrow" style="color:#478d19">Page not found</div><h1>Sorry, that page isn’t here.</h1><p>Head back to the <a href="index.html">home page</a> or <a href="contact.html">get in touch</a>.</p></div>'''
pages=[('index.html','Snack & Drink Vending Machines in Bournemouth & Dorset | Bryant Vending Services','Snack and drink vending machines for workplaces, gyms and venues in Bournemouth, Poole and Dorset. Machine at no charge subject to agreement, with commission or space rental options.',home),
('contact.html','Contact Us | Bryant Vending Services','Talk to Bryant Vending Services about a snack and drink vending machine for your workplace or venue in Bournemouth, Poole or Dorset. Call, WhatsApp or email.',contact),
('privacy.html','Privacy Notice | Bryant Vending Services','How Bryant Vending Services, a trading name of Bryant Group Holdings Ltd, uses personal information.',privacy),
('404.html','Page not found | Bryant Vending Services','Page not found.',notfound)]
for name,title,desc,body in pages: (p/name).write_text(page(name,title,desc,body).replace('href="index.html','href="/').replace('href="contact.html"','href="/contact.html"').replace('href="privacy.html"','href="/privacy.html"').replace('src="logo.png"','src="/logo.png"').replace('href="styles.css"','href="/styles.css"').replace('href="favicon.png"','href="/favicon.png"').replace('href="apple-touch-icon.png"','href="/apple-touch-icon.png"'))
(p/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+SITE+'/sitemap.xml\n')
(p/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{SITE}/{u}</loc></url>' for u in ['','contact.html','privacy.html'])+'</urlset>\n')
